/**
 * @file pcm_jd.h
 * @brief V90Jd / V92Jd (the phase-3 "Jd" frame holders and bit-serial codecs) and the V92MappingParams array helpers.
 *
 * Declares class V90Jd (15 member functions), class V92Jd (21) and the four C functions that allocate / free the arrays of a V92MappingParams block.
 * Definitions: pcm_jd.cpp.  Member order is the 32-bit layout (asserts generated by tools/layout_gen.py into pcm_jd_layout.inc).
 *
 * V90Jd / V92Jd hold the V.90 / V.92 Jd frames of phase 3 (the line probing result: a rate mask, constellation sizes, a look-ahead, a CRC-16) and their
 * bit-serial codec in one object.  They are plain classes (no virtual functions) embedded in V90Modem (V90Jd 0x90 bytes, V92Jd 0xdc bytes); the
 * constructors read words of the V90Parameters block.  The object keeps ONE byte-per-bit buffer starting at +2 that serves the transmitter
 * (packData() / getBitVector() build the frame in it from the "send" fields the setters and the constructor fill: rate-mask bits at +0x14 .. +0x23 and
 * +0x25 .., constellation sizes at +0x31 / +0x32, look-ahead bits at +0x33 / +0x34) and the receiver (unPackData() collects the bits of a frame at
 * +2 .. +0x31 after the start bits are dropped; getRatesMask() / getConstelationSize() / getMaxLookahead() read them back), so the two views overlap:
 * the transmit frame of 0x48 bytes (+2 .. +0x49) is `bits_`, and every "send" field is a byte of it.  V92Jd has a second buffer of 0x48 bytes at +0x4a
 * for the Jd phase frame (a 16-bit phase value; the constructor and setJdPhase() fill +0x5c .., the marker +0x79 is 1) and a state word per codec
 * (+0xd4 Jd data, +0xd8 Jd phase).
 *
 * The four free functions work on the V92MappingParams of v92_cp.h: `lcp_` (six arrays of 0x200 bytes) and `arr_` (four float arrays of 0x600 bytes)
 * are heap blocks OWNED by the block, allocated by V92createConstellations() / V92createFilterCoefficients() and freed by the delete functions
 * (V92setParamsInfoFromCPUnPck() only fills them).
 */
#ifndef DSP_CLASSES_P14_H
#define DSP_CLASSES_P14_H

#include "core/dsp_cxx.h"
#include "pcm_parameters.h" /* V90Parameters */
#include "v92_cp.h"         /* V92MappingParams */

/** V.90 Jd frame holder and codec (0x90 bytes); see the file comment. */
class V90Jd
{
public:
  explicit V90Jd(V90Parameters* p); /* both constructor variants are the same code */
  ~V90Jd();
  void setMaxLookahead(unsigned char v);                 /* unused */
  void setConstelSize(unsigned char a, unsigned char b); /* unused */
  void setRatesMask(int mask);                           /* unused */
  int getRatesMask();
  void getConstelationSize(unsigned char* a, unsigned char* b);
  unsigned char getMaxLookahead();
  void resetCrc(); /* unused */
  void packData(); /* unused: getBitVector() without the return value */
  void unPackReset();
  int unPackData(int bit);       /* receive state machine (9 states); 1 = frame complete */
  unsigned char* getBitVector(); /* builds the transmit frame; returns &bits_[0] */
public:
  uint8_t ones_;       ///< +0x00 receive: run length of one-bits (a frame starts after 17)
  uint8_t idx_;        ///< +0x01 receive: number of bits collected
  uint8_t bits_[0x48]; ///< +0x02 the frame buffer (TX frame / received bits), see the file comment
  uint8_t unk4a_[2];   ///< +0x4a unused padding
  uint32_t crc_[16];   ///< +0x4c CRC-16 shift register (parity words, taps 3 and 10)
  uint32_t state_;     ///< +0x8c receive state (0 .. 8)
};

/** V.92 Jd data / phase frame holder and codecs (0xdc bytes); see the file comment. */
class V92Jd
{
public:
  explicit V92Jd(V90Parameters* p); /* both constructor variants are the same code */
  ~V92Jd();
  void setJdPhase(float f);                              /* unused */
  void setMaxLookahead(unsigned char v);                 /* unused */
  void setRatesMask(int mask);                           /* unused */
  void setConstelSize(unsigned char a, unsigned char b); /* unused */
  float getJdPhase();
  int getRatesMask();
  void getConstelationSize(unsigned char* a, unsigned char* b);
  unsigned char getMaxLookahead();
  void resetCrc(); /* unused */
  void packJdPhaseData();
  void packJdData();
  void unPackJdReset();
  void unPackJdPhaseReset();
  int unPackJdPhaseData(int bit);       /* 9 states (state at +0xd8); 1 = frame complete */
  int unPackJdData(int bit);            /* 10 states (state at +0xd4); 1 = frame complete */
  unsigned char* getJdBitVector();      /* packJdData(); returns &bits_[0] */
  unsigned char* getJdPhaseBitVector(); /* packJdPhaseData(); returns &phase_[0] */
public:
  uint8_t ones_;        ///< +0x00 receive: run length of one-bits
  uint8_t idx_;         ///< +0x01 receive: number of bits collected (shared by both codecs)
  uint8_t bits_[0x48];  ///< +0x02 the Jd data frame buffer
  uint8_t phase_[0x48]; ///< +0x4a the Jd phase frame buffer
  uint8_t unk92_[2];    ///< +0x92 unused padding
  uint32_t crc_[16];    ///< +0x94 CRC-16 shift register (shared by both codecs)
  uint32_t stateJd_;    ///< +0xd4 receive state of the Jd data codec (0 .. 9)
  uint32_t statePhase_; ///< +0xd8 receive state of the Jd phase codec (0 .. 8)
};

extern "C"
{
  /* C symbols; the argument is the V92MappingParams of v92_cp.h (lcp_ at +0x84, arr_ at +0x5c in the 32-bit layout) */
  void V92createConstellations(V92MappingParams* p);     /* six sysdep_malloc(0x200), no NULL check */
  void V92createFilterCoefficients(V92MappingParams* p); /* four sysdep_malloc(0x600), no NULL check */
  void V92deleteConstellations(V92MappingParams* p);     /* sysdep_free of every non-NULL lcp_[k] in order; the pointers are NOT cleared */
  void V92deleteFilterCoefficients(V92MappingParams* p); /* sysdep_free of every non-NULL arr_[k] in order; the pointers are NOT cleared */
}

typedef V90Jd P14_V90Jd;
typedef V92Jd P14_V92Jd;

#include "pcm_jd_layout.inc"

#endif /* DSP_CLASSES_P14_H */
